import base64

import pages


def b64encode(s):
    return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii")


def make_cursor(score, item_id):
    payload = json.dumps({"score": score, "id": item_id}, separators=(",", ":"))
    return "h9:" + b64encode(payload)


def test_basic_order_score_desc_id_asc():
    items = [
        {"id": "a", "score": 1.0, "title": "A"},
        {"id": "b", "score": 3.0, "title": "B"},
        {"id": "c", "score": 2.0, "title": "C"},
        {"id": "d", "score": 3.0, "title": "D"},
    ]
    page, nxt = pages.list_page(items, None, 10)
    got = [x["id"] for x in page]
    assert got == ["b", "d", "c", "a"], got
    assert nxt is None
    # items not mutated
    assert items[0]["title"] == "A"


def test_first_page_none_cursor():
    items = [{"id": str(i), "score": float(i)} for i in range(10)]
    page, nxt = pages.list_page(items, None, 3)
    assert len(page) == 3
    assert nxt is not None


def test_walk_all_pages_no_dupes_no_missing():
    items = [{"id": "id-%03d" % i, "score": float((i * 7) % 13)} for i in range(25)]
    seen = []
    cursor = None
    while True:
        page, cursor = pages.list_page(items, cursor, 4)
        assert page, "page should not be empty mid-walk"
        for x in page:
            seen.append(x["id"])
        if cursor is None:
            break
    assert sorted(seen) == sorted(i["id"] for i in items)
    assert len(seen) == len(set(seen)) == len(items)


def test_walk_all_pages_size_one():
    items = [{"id": "id-%03d" % i, "score": float(i)} for i in range(20)]
    seen = []
    cursor = None
    while True:
        page, cursor = pages.list_page(items, cursor, 1)
        seen.append(page[0]["id"])
        if cursor is None:
            break
    expected = [x["id"] for x in sorted(items, key=lambda x: (-x["score"], x["id"]))]
    assert seen == expected


def test_ties_returned_exactly_once():
    items = [{"id": "x%d" % i, "score": 5.0, "title": "T"} for i in range(10)]
    items += [{"id": "hi", "score": 9.0, "title": "top"}, {"id": "lo", "score": 0.0}]
    seen = []
    cursor = None
    while True:
        page, cursor = pages.list_page(items, cursor, 3)
        for x in page:
            seen.append(x["id"])
        if cursor is None:
            break
    assert sorted(seen) == sorted(i["id"] for i in items)
    assert len(seen) == len(set(seen))
    tie_ids = [s for s in seen if s.startswith("x")]
    assert tie_ids == sorted(tie_ids)


def test_next_cursor_encodes_only_score_and_id():
    items = [{"id": "a", "score": 1.0, "title": "secret"}, {"id": "b", "score": 2.0, "title": "x"}]
    _, nxt = pages.list_page(items, None, 1)
    assert isinstance(nxt, str)
    assert "secret" not in nxt
    assert "x" not in nxt
    encoded = nxt[3:]
    payload = base64.urlsafe_b64decode(encoded.encode("utf-8")).decode("utf-8")
    obj = json.loads(payload)
    assert set(obj.keys()) == {"score", "id"}
